CREATE TABLE `sekai_memory_book_anime` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '番剧ID，主键，自增',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `title` varchar(100) NOT NULL COMMENT '番剧名称',
  `type` varchar(50) DEFAULT NULL COMMENT '番剧类型',
  `status` varchar(20) DEFAULT NULL COMMENT '观看状态',
  `score` decimal(3,1) DEFAULT NULL COMMENT '评分',
  `cover_url` varchar(1000) DEFAULT NULL COMMENT '番剧封面图片地址',
  `watch_date` date DEFAULT NULL COMMENT '观看日期',
  `memory_text` text COMMENT '个人回忆、观后感',
  `tags` varchar(255) DEFAULT NULL COMMENT '标签，用逗号分隔',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  `total_episodes` int DEFAULT NULL COMMENT '总集数',
  `current_episode` int DEFAULT NULL COMMENT '当前看到第几集',
  `last_watch_date` date DEFAULT NULL COMMENT '最近观看日期',
  `release_date` date DEFAULT NULL COMMENT '上映/开播日期',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=307 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='番剧回忆表';
