INSERT INTO `sekai_memory_book_anime` VALUES (1,3,'碧蓝档案','日本/日常/校园/机战/后宫','看完',10.0,'https://tse4-mm.cn.bing.net/th/id/OIP-C.uVP49xab1nOngGXwQ8uTgwHaFP?w=252&h=180&c=7&r=0&o=5&dpr=1.5&pid=1.7',NULL,'女主们都很好看！',NULL,'2026-05-03 13:48:57','2026-05-08 14:03:52',NULL,NULL,NULL,'2024-04-07'),(3,3,'SHINE POST','日本/青春/励志','想看',10.0,'https://tse3-mm.cn.bing.net/th/id/OIP-C.LJI_QYHDxiC-WbsWQOcThwAAAA?w=197&h=280&c=7&r=0&o=5&dpr=1.5&pid=1.7',NULL,'作为一个偶像番，剧情方面一坨狗屎，建议避坑',NULL,'2026-05-03 14:01:58','2026-05-08 14:03:52',NULL,NULL,NULL,'2022-07-13'),(4,3,'亚托莉 -我挚爱的时光','日本/科幻/恋爱','看完',10.0,'https://ts3.tc.mm.bing.net/th/id/OIP-C.gLT-AZbz-r5n9ceBD4HrrQHaJ4?rs=1&pid=ImgDetMain&o=7&rm=3','2026-05-12','太甜了，中间有点小刀子','科幻, 恋爱','2026-05-03 14:05:41','2026-06-27 00:20:19',13,13,'2026-05-12','2024-07-14'),(5,3,'寄宿学校的朱丽叶','日本/恋爱/青春/校园/魔法','看完',10.0,'https://image.9game.cn/2018/5/25/20439190.jpg','2026-05-12','很甜的恋爱番，紧张感和甜蜜感相结合','恋爱, 青春, 校园, 魔法','2026-05-03 14:12:40','2026-06-27 00:19:18',12,12,'2026-05-12','2018-10-06'),(6,3,'政宗君的复仇','日本/搞笑/恋爱/青春/校园/励志/美少女','看完',10.0,'https://myanimelist.net/images/anime/12/83709l.jpg','2026-05-12','是一部引发广泛讨论的校园恋爱动漫，虽然角色设定和剧情开局吸引人，但后期的发展和结局却让许多观众感到失望。','搞笑,恋爱,青春,校园,励志,美少女','2026-05-04 17:29:27','2026-05-12 19:12:45',12,12,'2026-05-12','2017-01-05'),(7,3,'政宗君的复仇第二季','日本/恋爱/校园/搞笑','看完',9.0,'https://myanimelist.net/images/anime/1667/135587l.jpg','2026-05-12','后期的发展和结局却让许多观众感到失望，只看第一季就行','恋爱,校园,搞笑','2026-05-04 17:31:21','2026-05-12 19:12:45',12,12,'2026-05-12','2023-07-03'),(9,3,'天气之子','日本/热血/战斗/科幻/奇幻/冒险','看完',10.0,'https://myanimelist.net/images/anime/1880/101146l.jpg','2026-05-12','影片的画质被认为是世界顶级水平，无论是阳光、雨滴还是城市景观，都非常生动，环境刻画和色调对比突出，尤其是雨天与阳光场景的冷暖碰撞，体现了主人公阳菜带来的温暖感受（知乎评价）。音乐方面，配乐精美动听，延续了新海诚作品一贯的高水准，增强了影片的情感感染力。','热血,战斗,科幻,奇幻,冒险','2026-05-04 17:34:26','2026-05-12 19:12:45',1,1,'2026-05-12','2019-07-19'),(10,3,'你的名字','日本/爱情/动画/剧情','看完',10.0,'https://myanimelist.net/images/anime/5/87048l.jpg','2026-05-12','厉害之处不仅仅是把一个时空穿梭灵魂互换的爱情故事拍的有血有肉，而且还能在讲清楚主线的情况下，通过无数的细节，埋伏下了许多主线以外的故事和情感，并且这些支线情感不但没显得杂乱，反而巧妙的烘托了主线。','爱情,动画,剧情','2026-05-04 17:36:22','2026-05-12 19:12:45',1,1,'2026-05-12','2016-08-26'),(11,3,'言叶之庭','日本/爱情/动画','看完',10.0,'https://ts1.tc.mm.bing.net/th/id/OIP-C.SyENNqdzqT5xwaxfjIRFrwHaKl?rs=1&pid=ImgDetMain&o=7&rm=3','2026-05-12','《言叶之庭》是一部视觉美丽、情感细腻的动画电影，尽管剧情简单，但通过新海诚独特的叙事风格和画面表现，展现了深刻的情感和人际关系。','爱情, 动画','2026-05-04 17:37:41','2026-06-27 00:18:08',1,1,'2026-05-12','2013-05-31'),(12,3,'秒速五厘米','日本/爱情/动画/剧情','看完',10.0,'https://myanimelist.net/images/anime/1410/112994l.jpg','2026-05-12','，我们好像能看到自己想故事，这就是电影的高明之处吧，让人产生深深的共情。我们永远会记得自己跋山涉水去见的那个人，那些自我感动的傻事，那些没有结果付出，大概每个人都经历过，再回过头看的时候，我从来不会觉得后悔，我坚信每一次相遇都有意义，享受每一次不期而遇的新人，会全身心付出自己，但我也从来不会委身求全放低姿态，势均力敌很重要，追不到的人就给他扬了吧\r\n\r\n作者：一只小白啊\r\n链接：https://www.zhihu.com/question/57086077/answer/2541989805\r\n来源：知乎\r\n著作权归作者所有。商业转载请联系作者获得授权，非商业转载请注明出处。','爱情,动画,剧情','2026-05-04 17:40:01','2026-05-12 19:12:45',1,1,'2026-05-12','2007-03-03'),(13,3,'可塑性记忆','日本/科幻/恋爱/催泪','看完',10.0,'https://myanimelist.net/images/anime/4/72750l.jpg','2026-05-12','《可塑性记忆》是一部以未来世界为背景，探讨生命、记忆与情感的催泪科幻动画，剧情感人、人物刻画细腻、主题深刻。','搞笑,科幻,恋爱,催泪','2026-05-04 17:42:26','2026-06-26 23:30:52',13,13,'2026-05-12','2015-04-05'),(14,3,'我想要吃掉你的胰脏','日本/爱情/动画/青春/剧情','看完',10.0,'https://myanimelist.net/images/anime/1768/93291l.jpg','2026-05-12','山内有樱名为良，树本无名只待春。\r\n\r\n樱花易逝，春树常青。\r\n\r\n你和我，都要好好活着。','爱情,动画,青春,剧情','2026-05-04 17:46:28','2026-05-12 19:12:45',1,1,'2026-05-12','2018-09-01'),(15,3,'选择项目','日本/百合,偶像,音乐','看完',10.0,'https://myanimelist.net/images/anime/1174/113554l.jpg','2026-05-12','剧情中规中矩吧，哥挺好听的，角色也塑造很好。','百合,偶像,音乐','2026-05-04 17:48:25','2026-05-12 20:49:09',13,13,'2026-05-12','2021-10-01'),(16,3,'超时空辉夜姬','日本/科幻/剧情/奇幻/音乐','看完',10.0,'https://tse3-mm.cn.bing.net/th/id/OIP-C.YdxFZbUjaXVwcpH9DnwT6gHaFm?w=239&h=181&c=7&r=0&o=5&dpr=1.5&pid=1.7',NULL,'《超时空辉夜姬》是一部高质量的动画电影，凭借其出色的音画体验和丰富的表现形式，赢得了观众的喜爱，但在故事节奏上存在一些不足。',NULL,'2026-05-04 17:55:40','2026-05-08 14:03:52',NULL,NULL,NULL,'2013-11-23'),(17,3,'古诺希亚','日本/科幻,悬疑,游戏改,热血,冒险','看完',10.0,'https://myanimelist.net/images/anime/1257/152352l.jpg','2026-05-12','《古诺希亚》是一款由游戏制作团队“小恶魔工作室”开发的科幻题材狼人杀单人游戏，后被改编为电视动画，以其独特的循环设定和深刻的剧情而备受好评。 故事发生在一艘宇宙飞船上，船员中混入了被称为“古诺希亚”的存在。 古诺希亚会伪装成人类，并逐一将船员从飞船上抹除。 主人公和其中一位船员 塞思 陷入了无尽的时间循环。 他们必须在一次次的讨论中揪出古诺希亚，同时寻找循环的真相和逃离的方法。','科幻,悬疑,游戏改,热血,冒险','2026-05-04 17:57:09','2026-05-12 20:49:09',21,21,'2026-05-12','2025-10-12'),(22,3,'剧场版世界计划 破碎的世界与无法歌唱的初音未来','日本/奇幻,音乐,偶像,青春,游戏改','看完',10.0,'https://myanimelist.net/images/anime/1883/144526l.jpg','2026-05-12','以无法把歌声传达出去的初音未来为线索，把“想被听见”的心情和各组合的舞台感连接起来；音乐、青春和陪伴感很适合收藏进回忆。','奇幻,音乐,偶像,青春,游戏改','2026-05-04 18:15:35','2026-05-12 20:49:09',1,1,'2026-05-12','2025-01-17'),(23,3,'BanG Dream! It\'s MyGO!!!!!','日本/励志,青春,校园,音乐','看完',10.0,'https://myanimelist.net/images/anime/1891/136948l.jpg','2026-05-12','把乐队、误解、创伤和重新靠近写得很细，角色之间不轻易和解的拉扯让“迷路也要继续演奏”的主题特别有重量。','励志,青春,校园,音乐','2026-05-04 18:15:35','2026-05-12 20:49:09',13,13,'2026-05-12','2023-06-29'),(24,3,'游戏人生','奇幻 / 异世界 / 游戏 / 喜剧','看完',10.0,'https://myanimelist.net/images/anime/1074/111944l.jpg',NULL,'空与白用游戏规则挑战异世界秩序，节奏明快、色彩鲜烈，智斗的爽感和兄妹搭档的默契都很突出。',NULL,'2026-05-04 18:15:35','2026-05-08 14:03:52',NULL,NULL,NULL,'2014-04-09'),(25,3,'我的青春恋爱物语果然有问题 第一季','日本/搞笑/恋爱/青春/校园/美少女','看完',10.0,'https://myanimelist.net/images/anime/1786/120117l.jpg','2026-05-12','从比企谷八幡的别扭视角切入青春关系，毒舌和社团委托背后藏着对真实关系的试探，第一季的锋利感很鲜明。','搞笑,恋爱,青春,校园,美少女','2026-05-04 18:15:35','2026-05-12 19:12:45',13,13,'2026-05-12','2013-04-05'),(26,3,'我的青春恋爱物语果然有问题 第二季','日本/搞笑/恋爱/青春/校园/美少女','看完',10.0,'https://myanimelist.net/images/anime/11/75376l.jpg','2026-05-12','侍奉部的关系开始真正裂开又重新寻找答案，第二季比第一季更重情绪和选择，“想要真物”的主题被推到台前。','搞笑,恋爱,青春,校园,美少女','2026-05-04 18:15:35','2026-05-12 19:12:45',13,13,'2026-05-12','2015-04-03'),(27,3,'我的青春恋爱物语果然有问题 第三季','日本/搞笑/恋爱/青春/校园/美少女','看完',10.0,'https://myanimelist.net/images/anime/1958/107912l.jpg','2026-05-12','围绕毕业舞会和各自的独立收束三人的关系，克制又酸涩，把八幡的青春以一种不完美但真诚的方式画上句点。','搞笑,恋爱,青春,校园,美少女','2026-05-04 18:15:35','2026-05-12 19:12:45',12,12,'2026-05-12','2020-07-10'),(28,3,'堀与宫村','日本/搞笑/恋爱/校园','看完',10.0,'https://myanimelist.net/images/anime/1695/111486l.jpg','2026-05-12','把校园里“公开的一面”和“私下的一面”写得很温柔，堀和宫村从偶然相识到彼此接住，甜得自然又不失青春的细腻。','搞笑,恋爱,校园','2026-05-04 18:29:33','2026-05-12 19:12:45',13,13,'2026-05-12','2021-01-10'),(29,3,'堀与宫村 piece','日本/恋爱/日常/搞笑','看完',10.0,'https://myanimelist.net/images/anime/1007/136277l.jpg','2026-05-12','补完本篇没展开的校园片段，像把大家共同度过的日子一块块拼回去，轻松、热闹，也很有毕业前回望青春的味道。','恋爱,日常,搞笑','2026-05-04 18:29:33','2026-05-12 19:12:45',13,13,'2026-05-12','2023-07-01'),(30,3,'破灭之国','日本/战斗/奇幻/魔法','看完',1.0,'https://myanimelist.net/images/anime/1610/138189l.jpg','2026-05-12','以魔女被科学帝国清算后的复仇为核心，世界观冷硬，情绪强烈，黑暗奇幻里的仇恨与救赎张力很鲜明。','战斗,奇幻,魔法','2026-05-04 18:29:33','2026-05-12 19:12:45',12,12,'2026-05-12','2023-10-07'),(31,3,'夏日口袋','日本/日常/恋爱/催泪/游戏改','看完',10.0,'https://myanimelist.net/images/anime/1691/148602l.jpg','2026-05-12','带着伤口来到鸟白岛的夏天，岛上的慢节奏、相遇和秘密一点点展开，Key 系作品那种清爽又催泪的余韵很足。','日常,恋爱,催泪,游戏改','2026-05-04 18:29:33','2026-05-12 19:12:45',26,26,'2026-05-12','2025-04-07'),(32,3,'莉可丽丝','日本/奇幻,战斗,百合','看完',10.0,'https://myanimelist.net/images/anime/1261/127311l.jpg','2026-05-12','千束和泷奈的搭档感是核心魅力，枪战动作轻快利落，咖啡店日常和地下组织任务之间的反差也特别抓人。','奇幻,战斗,百合','2026-05-04 18:29:33','2026-05-12 20:51:20',13,13,'2026-05-12','2022-07-02'),(33,3,'我家女友可不止可爱呢','日本/搞笑,恋爱,校园','看完',10.0,'https://myanimelist.net/images/anime/1995/121695l.jpg','2026-05-12','式守同学不只是可爱，关键时刻的帅气保护欲让反差感很亮；整体是甜度稳定、氛围轻松的校园恋爱日常。','搞笑,恋爱,校园','2026-05-04 18:29:33','2026-05-12 20:49:09',12,12,'2026-05-12','2022-04-10'),(34,3,'铃芽之旅','日本/奇幻,动画,剧情','看完',10.0,'https://myanimelist.net/images/anime/1598/128450l.jpg','2026-05-12','关门之旅把灾后记忆、成长和告别连在一起，沿途风景很开阔，情绪从奇幻冒险慢慢落到“好好活下去”的力量上。','奇幻,动画,剧情','2026-05-04 18:29:33','2026-05-12 20:49:09',1,1,'2026-05-12','2022-11-11'),(35,3,'通往夏天的隧道，离别的出口','日本/动画,剧情','看完',10.0,'https://myanimelist.net/images/anime/1462/125397l.jpg','2026-05-12','浦岛隧道用寿命交换愿望，把青春遗憾、逃避和靠近写成一个带时间代价的选择，清透又有淡淡疼痛感。','动画,剧情','2026-05-04 18:29:33','2026-05-12 20:49:09',1,1,'2026-05-12','2022-09-09'),(36,3,'游戏人生 零','奇幻 / 恋爱 / 剧情 / 剧场版','看完',10.0,'https://mya